public 
enum SpydusError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * Transport failure (DNS, TLS, connection, body read).
     */
    case Network(message: String)
    
    /**
     * URL does not start with `ORIGIN + "/"`.
     */
    case OriginForbidden(message: String)
    
    /**
     * Login issued no session cookie.
     */
    case CredentialsRejected(message: String)
    
    /**
     * No account meta-refresh / landed on `frmLogin`.
     */
    case NotLoggedIn(message: String)
    
    /**
     * Non-2xx upstream status, "no bib record link", …
     */
    case Upstream(message: String)
    
    case Parse(message: String)
    
    /**
     * AWS WAF answered instead of the library (`x-amzn-waf-action`, e.g. the UK's 405 captcha).
     * The native app shows the page for the user to complete, then passes the resulting cookie
     * back; the core never automates or bypasses it.
     */
    case HumanVerificationRequired(message: String)
    

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension SpydusError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSpydusError: FfiConverterRustBuffer {
    typealias SwiftType = SpydusError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SpydusError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Network(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .OriginForbidden(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .CredentialsRejected(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .NotLoggedIn(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .Upstream(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .Parse(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .HumanVerificationRequired(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SpydusError, into buf: inout [UInt8]) {
        switch value {

        

        
        case .Network(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .OriginForbidden(_ /* message is ignored*/):
            writeInt(&buf, Int32(2))
        case .CredentialsRejected(_ /* message is ignored*/):
            writeInt(&buf, Int32(3))
        case .NotLoggedIn(_ /* message is ignored*/):
            writeInt(&buf, Int32(4))
        case .Upstream(_ /* message is ignored*/):
            writeInt(&buf, Int32(5))
        case .Parse(_ /* message is ignored*/):
            writeInt(&buf, Int32(6))
        case .HumanVerificationRequired(_ /* message is ignored*/):
            writeInt(&buf, Int32(7))

        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSpydusError_lift(_ buf: RustBuffer) throws -> SpydusError {
    return try FfiConverterTypeSpydusError.lift(buf)
}

